// Gemeinsamer Rahmen der Root-Layouts (Welle 2, Länderrouting).
//
// Die Website hat drei Root-Layouts, damit <html lang> serverseitig stimmt:
//   src/app/(stamm)/layout.js          lang="de"     – gemeinsame Seiten, Portal, Login, Token-Strecken
//   src/app/(laender)/[land]/layout.js lang="de-DE" | "de-AT" | "de-CH" – Länderfassungen derselben Seiten
//   src/app/(en)/layout.js             lang="en"     – englische Fassungen derselben Seiten (/en, /en/at …)
// Land (Ländermodell) und Sprache (Sprachmodell) gehen als Kontext an alle Client-Komponenten
// (LandProvider, SpracheProvider).
// plus src/app/global-not-found.js für Pfade außerhalb aller Layouts.
// Ein Wechsel zwischen Root-Layouts lädt die Seite vollständig neu (Next.js) – gewollt.
//
// Alles, was vorher im einzigen Root-Layout stand (Schriften, Metadaten, JSON-LD,
// noindex außerhalb der Produktion, Sprunglink, LayoutWrapper, GA), steht jetzt hier.

import GoogleAnalytics from "@/components/Statistik/GoogleAnalytics";
import { Inter, Manrope } from "next/font/google";
import LayoutWrapper from "@/components/Reusable/LayoutWrapper";
import { GESELLSCHAFT, INDEXIERBAR, SITE } from "@/data/site";
import JsonLd from "@/components/JsonLd";
import { LandProvider } from "@/components/Land/LandKontext";
import { SpracheProvider } from "@/components/Sprache/SpracheKontext";
import { LAND_AUS_PFAD } from "@/lib/land/laender";
import { verifizierungMetadaten } from "@/lib/verifizierung";

export { LAND_AUS_PFAD };

// Zwei Schriften wie auf oekovolt.de: Inter für Fließtext, Manrope für
// Überschriften. next/font hostet beide selbst (keine Verbindung zu Google).
const inter = Inter({
  subsets: ["latin", "latin-ext"],
      url: BASE_URL,
      logo: { "@type": "ImageObject", "@id": `${BASE_URL}/#logo`, url: `${BASE_URL}/icon-512.png`, width: 512, height: 512, caption: "ÖkoInvest" },
      image: { "@id": `${BASE_URL}/#logo` },
      description: SITE.kurz,
      slogan: SITE.claim,
      foundingDate: "2020-09-10",
      address: {
        "@type": "PostalAddress",
        streetAddress: GESELLSCHAFT.sitz,
        addressLocality: GESELLSCHAFT.ort,
        postalCode: GESELLSCHAFT.plz,
        addressCountry: "AT",
      },
      identifier: { "@type": "PropertyValue", propertyID: "Firmenbuchnummer", value: GESELLSCHAFT.register },
      parentOrganization: { "@type": "Organization", name: "ÖKOVOLT Gruppe", url: SITE.gruppeUrl },
      areaServed: [
      icon: [
        { url: "/icon.svg", type: "image/svg+xml" },
        { url: "/icon-192.png", sizes: "192x192", type: "image/png" },
      ],
      shortcut: "/icon.svg",
      apple: [{ url: "/apple-touch-icon.png", sizes: "180x180", type: "image/png" }],
    },
    // Bestätigungscodes für Google Search Console / Bing Webmaster Tools – erst
    // nach Festlegung der Produktivdomain über Umgebungsvariablen setzen (nur gültige Codes, src/lib/verifizierung.js).
    ...verifizierungMetadaten({ google: process.env.NEXT_PUBLIC_GSC_VERIFICATION, bing: process.env.NEXT_PUBLIC_BING_VERIFICATION }),
    openGraph: {
      type: "website",
      locale: ogLocale,
      url: BASE_URL,
      siteName: "ÖkoInvest",
      title: TITEL,
      description: BESCHREIBUNG,
      images: [{ url: `${BASE_URL}/img/solarpark-himmel.jpg`, width: 1280, height: 852, alt: t.bildAlt }],
    },
    twitter: { card: "summary_large_image", title: TITEL, description: BESCHREIBUNG, images: [`${BASE_URL}/img/solarpark-himmel.jpg`] },
    // Paket I: Indexierung nur in der echten Produktion (INDEXIERBAR, src/data/site.js).
    robots: INDEXIERBAR
      ? {
          index: true,
          follow: true,
          googleBot: { index: true, follow: true, "max-video-preview": -1, "max-image-preview": "large", "max-snippet": -1 },
        }
      : { index: false, follow: false, nocache: true },
    referrer: "origin-when-cross-origin",
    formatDetection: { email: false, address: false, telephone: false },
  };
}

/**
 * <html>/<body> mit allem, was jede Seite braucht.
 * @param {{ lang: string, sprache?: "de"|"en", land?: "DE"|"AT"|"CH"|null|"pfad", children: any }} p
 *   land = LAND_AUS_PFAD: Land im Browser aus dem Pfad (englische Seiten, ein Root-Layout für /en/**)
 */
export default function Wurzel({ lang, sprache = "de", land = null, children }) {
  return (
    <html lang={lang} dir="ltr" className={`${inter.variable} ${manrope.variable}`}>
      <body className="bg-white text-ink-900">
        {/* Paket I: Außerhalb der Produktion zusätzlich ein festes noindex (React
            hebt <meta> in den <head>). Seiten mit eigenem robots-Eintrag
            (index: true) überschreiben das metadata-Feld; bei zwei
            robots-Angaben gilt für Suchmaschinen die strengere. */}
        {!INDEXIERBAR && <meta name="robots" content="noindex, nofollow" />}
        <a href="#main-content" className="sr-only focus:not-sr-only focus:absolute focus:top-2 focus:left-2 focus:z-[9999] focus:px-4 focus:py-2 focus:bg-ov-600 focus:text-white focus:rounded">
          {(sprache === "en" ? TEXTE.en : TEXTE.de).sprung}
        </a>
        <JsonLd daten={siteSchema(lang)} />
        <SpracheProvider sprache={sprache}>
          <LandProvider land={land}>
            <LayoutWrapper>{children}</LayoutWrapper>
          </LandProvider>
        </SpracheProvider>
        <GoogleAnalytics />
      </body>
    </html>
  );
}
// src/lib/land/schreibweise.js – Schweizer Schreibweise (W3-0, QM-Rest Ländermodell)
//
// In der Schweiz gibt es kein „ß“: Auf /ch/… und /en/ch/… wird es zentral durch „ss“ ersetzt
// (ẞ → SS). Die Texte bleiben in den Komponenten unverändert (eine Seite, ein Text); die
// Umschreibung passiert dort, wo Texte ausgegeben werden:
//   - useTexte() und <T> (Client, src/components/Sprache/…) mit dem Land aus dem Root-Layout
//   - uebersetze() / inhaltFuer() (Server und Client, src/lib/sprache/woerterbuch.js, ./inhalte.js)
//   - Navigation und Footer (navigationFuer() über schreibweiseFuer())
//   - Metadaten der Länderfassungen (seitenMetadata(), ./seite.js)
// Technische Felder (href, id, slug, Bilder, Icons, Schlüssel) bleiben unberührt, ebenso
// React-Elemente und Funktionen.
//
// Relative Importe mit Dateiendung (node:test ohne Alias-Auflösung).

import { landCode } from "./laender.js";

const TECHNISCH = new Set(["href", "id", "slug", "bild", "src", "icon", "ton", "typ", "key", "schluessel", "url", "pfad"]);

/** "Straße" → "Strasse", "GROẞ" → "GROSS"; andere Werte unverändert. */
export function ohneEszett(text) {
  return typeof text === "string" && /[ßẞ]/.test(text) ? text.replace(/ß/g, "ss").replace(/ẞ/g, "SS") : text;
}

const istSchlicht = (x) => x !== null && typeof x === "object" && !x.$$typeof && (Object.getPrototypeOf(x) === Object.prototype || Object.getPrototypeOf(x) === null);

// Textfunktionen (z. B. lead: (n) => `… ${n} …`) bekommen eine Hülle, die ihr Ergebnis umschreibt.
// Je Funktion genau eine Hülle (stabile Identität). Komponenten (Name mit Großbuchstaben) bleiben.
const HUELLEN = new WeakMap();
function textFunktion(fn) {
  if (/^[A-Z]/.test(fn.name || "")) return fn;
  if (!HUELLEN.has(fn)) HUELLEN.set(fn, (...args) => schweizerSchreibweise(fn(...args)));
  return HUELLEN.get(fn);
}

/**
 * Tief: alle Strings in schlichten Objekten und Listen ohne „ß“; Textfunktionen liefern ihr Ergebnis
 * ohne „ß“. Unverändert bleiben technische Felder, React-Elemente, Komponenten, Klasseninstanzen
 * (Date, Map …) und Zahlen. Gibt dasselbe Objekt zurück, wenn nichts zu ändern ist.
 */
export function schweizerSchreibweise(wert, tiefe = 0) {
  if (typeof wert === "string") return ohneEszett(wert);
  if (typeof wert === "function") return textFunktion(wert);
  if (tiefe > 12) return wert;
  if (Array.isArray(wert)) {
    let geaendert = false;
    const out = wert.map((w) => {
      const n = schweizerSchreibweise(w, tiefe + 1);
      if (n !== w) geaendert = true;
      return n;
    });
    return geaendert ? out : wert;
  }
  if (istSchlicht(wert)) {
    let geaendert = false;
    const out = {};
    for (const k of Object.keys(wert)) {
      const n = TECHNISCH.has(k) ? wert[k] : schweizerSchreibweise(wert[k], tiefe + 1);
      if (n !== wert[k]) geaendert = true;
      out[k] = n;
    }
    return geaendert ? out : wert;
  }
  return wert;
}

/** Nur in der Schweiz (Länderfassung /ch und /en/ch) umschreiben, sonst unverändert. */
export function schreibweiseFuer(wert, land) {
  return landCode(land) === "CH" ? schweizerSchreibweise(wert) : wert;
}
// Zentrale, sichere Ausgabe von strukturierten Daten (JSON-LD, schema.org).
//
// Warum: JSON.stringify escapt kein "<". Steht in einem Wert (z. B. Projekttitel aus
// Anbietereingaben) "</script><script>…", beendet der Browser den Script-Block und führt
// den Rest aus (gespeicherte XSS). Siehe docs/MASTERPLAN-DACH.md Abschnitt 3, Befund 7.
//
// Bewusst ohne JSX (React.createElement), damit die Datei auch direkt mit
// `node --test` importierbar ist. Kein "use client": Server-Komponente, rendert reines HTML.
// Test: node --test src/components/JsonLd.test.mjs

import { createElement } from "react";

// Zeichen, die im HTML-Kontext eines <script>-Blocks gefährlich sind, als JSON-Unicode-Escapes.
// Die Escapes sind gültiges JSON und ergeben nach JSON.parse exakt den Originaltext.
// - "<" verhindert "</script>" und "<!--"
// - ">" verhindert "-->" sowie Fehlinterpretation in Parsern
// - "&" verhindert Entity-Deutung, falls der Inhalt einmal als XHTML/Attribut landet
// - U+2028/U+2029 sind in JSON erlaubt, waren in älteren JS-Engines aber Zeilenumbrüche
// Als Codepunkte notiert, damit keine unsichtbaren Zeichen im Quelltext stehen.
const LS = String.fromCharCode(0x2028);
const PS = String.fromCharCode(0x2029);
const ERSATZ = {
  "<": "\\u003c",
  ">": "\\u003e",
  "&": "\\u0026",
  [LS]: "\\u2028",
  [PS]: "\\u2029",
};
const MUSTER = new RegExp(`[<>&${LS}${PS}]`, "g");

/**
 * Serialisiert Daten als JSON und escapt alle für einen `<script>`-Block gefährlichen Zeichen.
 *
 * @param {object|object[]} daten  schema.org-Objekt oder Liste von Objekten (ein `@graph`
 *                                 ist ebenfalls einfach ein Objekt).
 * @returns {string} sicherer Text für den Inhalt von `<script type="application/ld+json">`.
 * @throws {TypeError} wenn `daten` nicht als JSON darstellbar ist (z. B. `undefined`, Funktion,
 *                     zirkuläre Struktur, BigInt) – lieber laut scheitern als leeres JSON-LD.
 */
export function jsonLdText(daten) {
  const json = JSON.stringify(daten);
  if (typeof json !== "string") {
    throw new TypeError("JsonLd: daten sind nicht als JSON darstellbar");
  }
  return json.replace(MUSTER, (z) => ERSATZ[z]);
}

/**
 * Gibt strukturierte Daten als `<script type="application/ld+json">` aus – immer escapt.
 *
 * Einzige erlaubte Stelle für JSON-LD auf der Website. Keine eigenen
 * `dangerouslySetInnerHTML`-Blöcke mit `JSON.stringify` mehr anlegen.
 *
 * @example
 * import JsonLd from "@/components/JsonLd";
 *
 * <JsonLd daten={{ "@context": "https://schema.org", "@type": "Service", name: titel }} />
 * <JsonLd daten={[organisation, breadcrumb]} />          // mehrere Objekte in einem Block
 * <JsonLd daten={faq} id="faq-jsonld" />                 // optionale id
 * <JsonLd daten={faq} nonce={nonce} />                   // für eine spätere Nonce-CSP (Paket A)
 *
 * @param {object} props
 * @param {object|object[]|null|undefined} props.daten  Inhalt; `null`/`undefined` rendert nichts.
 * @param {string} [props.id]     optionales id-Attribut des Script-Elements.
 * @param {string} [props.nonce]  optionaler CSP-Nonce.
 * @returns {import("react").ReactElement|null}
 */
export default function JsonLd({ daten, id, nonce }) {
  if (daten === null || daten === undefined) return null;
  return createElement("script", {
    type: "application/ld+json",
    id,
    nonce,
    dangerouslySetInnerHTML: { __html: jsonLdText(daten) },
  });
}

export { JsonLd };

