      if (out[k] !== knoten[k]) anders = true;
    }
    return anders ? out : knoten;
  }
  const props = knoten.props || {};
  const neu = {};
  let geaendert = false;
  for (const k of Object.keys(props)) {
    if (TECHNISCH.has(k) || typeof props[k] === "function") continue;
    const n = baum(props[k], tiefe + 1);
    if (n !== props[k]) {
      neu[k] = n;
      geaendert = true;
    }
