/** JSX-Baum in der Schweiz (Länderfassung /ch, /en/ch) ohne „ß“; sonst unverändert. */
export function schreibweiseBaum(knoten, land) {
  return landCode(land) === "CH" ? baum(knoten, 0) : knoten;
}

