// notFound(), redirect() …), bleibt er unverändert im Baum und React rendert ihn wie gewohnt.

const istServerKomponente = (typ) => typeof typ === "function" && typ.$$typeof === undefined && !typ.prototype?.isReactComponent;

async function tiefListe(arr, tiefe) {
  let geaendert = false;
  const out = [];
  for (const k of arr) {
    const n = await tief(k, tiefe + 1);
    if (n !== k) geaendert = true;
    out.push(n);
  }
  return geaendert ? out : arr;
}

async function tief(knoten, tiefe) {
  if (typeof knoten === "string") return ohneEszett(knoten);
  if (tiefe > 200 || knoten === null || typeof knoten !== "object") return knoten;
  if (Array.isArray(knoten)) return tiefListe(knoten, tiefe);
  if (!isValidElement(knoten)) {
    if (knoten.$$typeof || Object.getPrototypeOf(knoten) !== Object.prototype) return knoten;
    let anders = false;
    const out = {};
    for (const k of Object.keys(knoten)) {
      out[k] = TECHNISCH.has(k) && k !== "children" ? knoten[k] : await tief(knoten[k], tiefe + 1);
      if (out[k] !== knoten[k]) anders = true;
    }
    return anders ? out : knoten;
  }
  if (istServerKomponente(knoten.type)) {
    let ergebnis;
    try {
      ergebnis = await knoten.type(knoten.props);
    } catch {
      return tiefElement(knoten, tiefe); // React rendert den Baustein selbst (und meldet den Fehler dort)
    }
