    return knoten.key != null ? createElement(Fragment, { key: knoten.key }, neu) : neu;
  }
  return tiefElement(knoten, tiefe);
}

async function tiefElement(knoten, tiefe) {
  const props = knoten.props || {};
  const neu = {};
  let geaendert = false;
  for (const k of Object.keys(props)) {
    if (TECHNISCH.has(k) || typeof props[k] === "function") continue;
    const n = await tief(props[k], tiefe + 1);
    if (n !== props[k]) {
      neu[k] = n;
      geaendert = true;
    }
