  assert.doesNotMatch(html.replace(/(id|href)="[^"]*"/g, ""), /ß/);
  assert.match(html, /<div title="Mass"><h2>Grossspeicher: Grösse<\/h2><em>weiss aussen<\/em><\/div>/);
  assert.match(html, /<p>Fliesstext<\/p>/);
  assert.match(html, /Grossspeicher: Fuss/);
});
