class Spaeter {
  constructor(versprechen) {
    this.versprechen = versprechen;
  }
}
const dann = (wert, fn) => (wert instanceof Spaeter ? new Spaeter(wert.versprechen.then(fn).then((x) => (x instanceof Spaeter ? x.versprechen : x))) : fn(wert));
const alle = (liste) => (liste.some((x) => x instanceof Spaeter) ? new Spaeter(Promise.all(liste.map((x) => (x instanceof Spaeter ? x.versprechen : x)))) : liste);
const istThenable = (x) => x !== null && typeof x === "object" && typeof x.then === "function";
const FEHLER = Symbol("Baustein nicht ausführbar");

const istServerKomponente = (typ) => typeof typ === "function" && typ.$$typeof === undefined && !typ.prototype?.isReactComponent;

function tief(knoten, tiefe) {
  if (typeof knoten === "string") return ohneEszett(knoten);
  if (tiefe > 200 || knoten === null || typeof knoten !== "object") return knoten;
  if (Array.isArray(knoten)) {
    return dann(alle(knoten.map((k) => tief(k, tiefe + 1))), (out) => (out.some((n, i) => n !== knoten[i]) ? out : knoten));
  }
  if (!isValidElement(knoten)) {
    // schlichte Objekte in Props (z. B. pill={{ text: "…" }}): Texte umschreiben
    if (knoten.$$typeof || Object.getPrototypeOf(knoten) !== Object.prototype) return knoten;
    const namen = Object.keys(knoten);
    return dann(alle(namen.map((k) => (TECHNISCH.has(k) && k !== "children" ? knoten[k] : tief(knoten[k], tiefe + 1)))), (werte) =>
      werte.some((w, i) => w !== knoten[namen[i]]) ? Object.fromEntries(namen.map((k, i) => [k, werte[i]])) : knoten,
    );
  }
  if (istServerKomponente(knoten.type)) {
    let ergebnis;
    try {
      ergebnis = knoten.type(knoten.props);
    } catch {
      return tiefElement(knoten, tiefe); // React rendert den Baustein selbst (und meldet den Fehler dort)
    }
    if (istThenable(ergebnis)) ergebnis = new Spaeter(Promise.resolve(ergebnis).catch(() => FEHLER));
